import Article from '../../components/client/Article';
import { useState, useEffect } from 'react';
import '../../styles/shoppingList.css';

function ShoppingList({ cartItems, setCartItems }) {
    // 1. Les états (States)
    const [itemsList, setItemsList] = useState([]); // La liste originale (intacte)
    const [displayedItems, setDisplayedItems] = useState([]); // La liste filtrée à afficher

    // Les états pour les filtres et le tri
    const [searchTerm, setSearchTerm] = useState('');
    const [maxPrice, setMaxPrice] = useState(2000); // Valeur par défaut haute
    const [sortOption, setSortOption] = useState('');

    // 2. Récupération des données au montage
    useEffect(() => {
        fetch('http://localhost:3001/')
            .then(response => response.json())
            .then(data => {
                setItemsList(data);
                setDisplayedItems(data);
            })
            .catch(error => {
                console.error('Erreur lors de la récupération des articles :', error);
            });
    }, []);

    // 3. Logique de filtrage et de tri (se déclenche à chaque changement de critère)
    useEffect(() => {
        // --- ÉTAPE A : Le Filtrage (Recherche + Critères multiples) ---
        let filtered = itemsList.filter(item => {
            // Filtre par barre de recherche (sur le nom)
            const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
            
            // Filtre par critère (Ex: Prix maximum)
            const matchPrice = item.price <= maxPrice;

            // L'article doit correspondre à TOUS les critères
            return matchSearch && matchPrice;
        });

        // --- ÉTAPE B : Le Tri ---
        // On utilise [...filtered] pour créer une copie car .sort() modifie le tableau original
        let sorted = [...filtered]; 
        
        if (sortOption === 'price-asc') {
            sorted.sort((a, b) => a.price - b.price);
        } else if (sortOption === 'price-desc') {
            sorted.sort((a, b) => b.price - a.price);
        } else if (sortOption === 'name-asc') {
            sorted.sort((a, b) => a.name.localeCompare(b.name));
        } else if (sortOption === 'name-desc') {
            sorted.sort((a, b) => b.name.localeCompare(a.name));
        }

        // --- ÉTAPE C : Mise à jour de l'affichage ---
        setDisplayedItems(sorted);
    }, [searchTerm, maxPrice, sortOption, itemsList]); // Le useEffect s'exécute si une de ces variables change

    // 4. Réinitialisation
    const handleReset = (e) => {
        e.preventDefault(); // Évite le rechargement de page
        setSearchTerm('');
        setMaxPrice(2000);
        setSortOption('');
    };

    return (
        <div className="shopping-page">
            {/* Panneau de filtres à gauche */}
            <aside className="filter-sidebar">
                <h3>Filtrer les articles</h3>
                
                <form className="filter-form">
                    <div className="filter-group">
                        <label>Rechercher :</label>
                        <input 
                            type="text" 
                            placeholder="Planche, combinaison..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>

                    <div className="filter-group">
                        <label>Prix maximum : {maxPrice}€</label>
                        <input 
                            type="range" 
                            min="0" 
                            max="2000" 
                            step="50"
                            value={maxPrice}
                            onChange={(e) => setMaxPrice(Number(e.target.value))}
                        />
                    </div>

                    <div className="filter-group">
                        <label>Trier par :</label>
                        <select value={sortOption} onChange={(e) => setSortOption(e.target.value)}>
                            <option value="">Pertinence</option>
                            <option value="price-asc">Prix : Croissant</option>
                            <option value="price-desc">Prix : Décroissant</option>
                            <option value="name-asc">Nom : A à Z</option>
                            <option value="name-desc">Nom : Z à A</option>
                        </select>
                    </div>

                    <button className="btn-reset" onClick={handleReset}>Réinitialiser les filtres</button>
                </form>
            </aside>

            {/* Affichage des articles à droite */}
            <main className="article-container">
                {displayedItems.length === 0 ? (
                    <div className="no-results-message">
                        <p>Désolé, aucun article ne correspond à vos critères de recherche. 🏄‍♂️</p>
                    </div>
                ) : (
                    displayedItems.map((article) => (
                        <Article key={article.idItem} article={article} cartItems={cartItems} setCartItems={setCartItems} />
                    ))
                )}
            </main>
        </div>
    );
}

export default ShoppingList;
